/**
 * Hand-written typings for the Emscripten glue generated by native/build.ps1
 * (src/sim/wasm/rocketsim.js). Mirrors native/rs_api.h. All pointers are byte offsets into
 * `wasmMemory.buffer`. Only RocketSimBridge.ts should import this module.
 */

export interface RocketSimModule {
  readonly wasmMemory: WebAssembly.Memory;
  /** Heap views. They are REPLACED when memory grows; prefer views over wasmMemory.buffer. */
  HEAPF32: Float32Array;
  HEAP32: Int32Array;
  HEAPU8: Uint8Array;

  _malloc(bytes: number): number;
  _free(ptr: number): void;

  _rs_init_arena_mesh(verticesPtr: number, numVertices: number, trianglesPtr: number, numTriangles: number): number;
  /** Field layout floats (see rs_api.h); 0 ok, 1 bad data, 2 wrong pad count, 3 arena exists. */
  _rs_set_field_layout(dataPtr: number, count: number): number;
  /** 0 ok, 2 no mesh, 4 no field layout. */
  _rs_arena_create(tickRate: number): number;
  _rs_arena_destroy(): void;

  _rs_add_car(team: number, preset: number): number;
  _rs_remove_car(carId: number): number;
  _rs_get_car_config(preset: number, out22Ptr: number): void;
  _rs_set_controls(
    carId: number,
    throttle: number,
    steer: number,
    pitch: number,
    yaw: number,
    roll: number,
    jump: number,
    boost: number,
    handbrake: number,
  ): void;
  _rs_set_car_state(
    carId: number,
    x: number,
    y: number,
    z: number,
    yaw: number,
    pitch: number,
    roll: number,
    vx: number,
    vy: number,
    vz: number,
    avx: number,
    avy: number,
    avz: number,
  ): void;
  _rs_set_car_boost(carId: number, boost: number): void;
  _rs_set_car_dodge_deadzone(carId: number, deadzone: number): void;
  _rs_demolish_car(carId: number): void;

  _rs_set_ball_state(
    x: number,
    y: number,
    z: number,
    vx: number,
    vy: number,
    vz: number,
    avx: number,
    avy: number,
    avz: number,
  ): void;

  _rs_step(n: number): void;
  _rs_sync(): void;
  _rs_state_ptr(): number;
  _rs_reset_kickoff(seed: number): void;
  _rs_is_ball_scored(): number;
  /** Writes x, y, z, isBig of pad `index` at out4Ptr; returns 1, or 0 (no arena / bad index). */
  _rs_get_boost_pad(index: number, out4Ptr: number): number;

  _rs_ball_pred_update(): void;
  _rs_ball_pred_force(): void;
  _rs_ball_pred_ptr(): number;

  _rs_set_demo_mode(demoMode: number): void;
  _rs_set_unlimited_boost(enabled: number): void;

  // Full state save / load (netcode rollback). See rs_api.h for the codes and the blob layout.
  /** Writes the state blob at outPtr (at most cap bytes); returns its length or -1. */
  _rs_save_state(outPtr: number, cap: number): number;
  /** 0 ok, 1 no arena, 2 bad magic / version, 3 roster mismatch, 4 truncated / corrupt. */
  _rs_load_state(dataPtr: number, len: number): number;
  /** Upper bound of a blob for MAX_CARS cars (constant for the module lifetime). */
  _rs_state_size_max(): number;
  /** FNV-1a 32 of the bytes _rs_save_state would produce now (as a signed i32: use `>>> 0`). */
  _rs_state_hash(): number;
  /** 6 int8 per slot at packedPtr (throttle, steer, pitch, yaw, roll, buttons bit0 jump / bit1 boost / bit2 handbrake). */
  _rs_set_controls_packed(packedPtr: number, numSlots: number): void;

  _rs_version(): number;
}

export interface RocketSimModuleOptions {
  /** Override where the .wasm is fetched from (defaults to next to rocketsim.js). */
  locateFile?(path: string, scriptDirectory: string): string;
  /** The .wasm bytes: the glue compiles them itself (WebAssembly.instantiate(bytes, imports)). */
  wasmBinary?: ArrayBuffer | Uint8Array;
  /**
   * Instantiate a precompiled module instead of locating / fetching / compiling the .wasm. The glue
   * calls this before it looks for the binary, so no fetch, instantiateStreaming or node `fs` read
   * ever happens; it is what workerd needs (WebAssembly.instantiate(bytes) is forbidden there, but
   * `new WebAssembly.Instance(importedModule, imports)` is allowed). Call `successCallback` with the
   * instance; the return value (the exports, or {}) is ignored by the glue.
   */
  instantiateWasm?(
    imports: WebAssembly.Imports,
    successCallback: (instance: WebAssembly.Instance) => void,
  ): WebAssembly.Exports | Record<string, never>;
  print?(text: string): void;
  printErr?(text: string): void;
}

export default function createRocketSim(options?: RocketSimModuleOptions): Promise<RocketSimModule>;
